from __future__ import annotations

import html

from gems27.promotion import promotion_gate


def esc(value):
    return html.escape(str(value), quote=True)


def source(path, title):
    return f'<a href="../{esc(path)}">{esc(title)}</a>'


def current_notice(card):
    # Never trust a card's self-declared verdict or submission_ready flag. Even a
    # complete evidence schema is eligibility for a separate selector, not upload.
    gate = promotion_gate(card)
    state = "Evidence schema eligible; no slot selected" if gate["promotion_eligible"] else "Evidence gates incomplete or failed"
    return f'''<section class="readiness-banner" id="download" aria-label="Current submission readiness" data-submission-ready="false">
  <div class="eyebrow">Automated submission safety · 2026-10-25</div>
  <h2>Current run: NOT READY TO SUBMIT — NO FILE APPROVED</h2>
  <p><strong>No new TIFF is approved. Do not upload any file from this site at present.</strong> {esc(state)}. The advertised historical primary also fails the dot-overlap rule; a valid file format does not clear a duplicate lane.</p>
  <div class="download-actions"><button class="button" type="button" disabled aria-disabled="true">Submission download locked</button><a class="button quiet" href="submission-review.html">See automated checks</a><a href="data/run_card_2026-10-25.json" download>Download JSON run card</a></div>
  <p class="small">No human-inspector sign-off is required or substituted. No competition slot selected. Existing TIFFs are archived references, not new submission recommendations.</p>
</section>'''


